using System.Globalization;using System.Windows;using System.Windows.Controls;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;namespace AutoPecasERP.Desktop.Views;public partial class EstoqueWindow:Window{readonly int id;public EstoqueWindow(int produtoId){InitializeComponent();id=produtoId;Carregar();}async void Carregar(){using var db=new ErpDbContext();var p=await db.Produtos.FindAsync(id);if(p==null)return;Titulo.Text=$"{p.CodigoInterno} — {p.Descricao}";Saldo.Text=$"Saldo atual: {p.EstoqueAtual:N2} | Local: {p.Localizacao}";GridDados.ItemsSource=await db.MovimentacoesEstoque.Where(x=>x.ProdutoId==id).OrderByDescending(x=>x.Data).Take(100).ToListAsync();}async void Confirmar_Click(object s,RoutedEventArgs e){if(!decimal.TryParse(Quantidade.Text.Replace(",","."),NumberStyles.Any,CultureInfo.InvariantCulture,out var q)||q<=0){MessageBox.Show("Quantidade inválida.");return;}using var db=new ErpDbContext();var p=await db.Produtos.FindAsync(id);if(p==null)return;var tipo=((ComboBoxItem)Tipo.SelectedItem).Content.ToString()!;var anterior=p.EstoqueAtual;decimal posterior=tipo=="ENTRADA"?anterior+q:tipo=="SAIDA"?anterior-q:q;if(posterior<0){MessageBox.Show("Estoque insuficiente.");return;}p.EstoqueAtual=posterior;db.MovimentacoesEstoque.Add(new MovimentacaoEstoque{ProdutoId=id,Tipo=tipo,Quantidade=q,SaldoAnterior=anterior,SaldoPosterior=posterior,Documento=Documento.Text.Trim(),Observacao=Observacao.Text.Trim()});await db.SaveChangesAsync();Carregar();}}